import 'package:deepseek_api/deepseek_api.dart';

final deepseek = DeepSeekAPI(apiKey: 'your-api-key');
final response = await deepseek.createChatCompletion(
  ChatCompletionRequest(
    model: 'deepseek-chat',
    messages: [ChatMessage(role: 'user', content: 'Explain quantum computing in 50 words')],
    temperature: 0.7,
    maxTokens: 100,
  ),
);
print(response.choices.first.message.content);
